WITH base AS (SELECT id, session_id, event_type, page, event_time, duration_sec, TRIM(page) AS clean_page FROM web_events WHERE event_time >= TO_TIMESTAMP('2024-05-11 05:00:00') AND duration_sec IS NOT NULL), gaps AS (SELECT *, CASE WHEN LAG(event_time) OVER (PARTITION BY session_id ORDER BY event_time ASC, id ASC) IS NULL OR event_time > LAG(event_time) OVER (PARTITION BY session_id ORDER BY event_time ASC, id ASC) + INTERVAL 30 DAYS THEN 1 ELSE 0 END AS session_start_flag FROM base), sessionized AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY session_id ORDER BY event_time ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM gaps), enriched AS (SELECT *, NTILE(4) OVER (PARTITION BY event_type ORDER BY duration_sec ASC, id ASC) AS duration_sec_bucket, CUME_DIST() OVER (PARTITION BY page ORDER BY duration_sec ASC NULLS LAST) AS duration_sec_cume_dist, MIN(island_id) OVER w_hist AS event_type_min_island_id FROM sessionized WINDOW w_hist AS (PARTITION BY event_type)), cleaned AS (SELECT id, session_id, event_type, page, event_time, duration_sec, clean_page, island_id, duration_sec_bucket, duration_sec_cume_dist, event_type_min_island_id, CEIL(island_id) AS island_id_whole FROM enriched WHERE event_time >= TIMESTAMP '2023-06-22 16:00:00' AND page IS NOT NULL), kept_keys AS (SELECT id FROM cleaned EXCEPT ALL SELECT id FROM web_events WHERE event_type NOT IN ('add_to_cart', 'click')), reconciled AS (SELECT s.* FROM cleaned s INNER JOIN kept_keys k ON s.id = k.id), cleaned_web_events AS (SELECT *, CONCAT(page, '/', event_type) AS page_event_type, DATE_FORMAT(event_time, 'yyyy-MM-dd') AS event_time_label FROM reconciled WHERE event_type_min_island_id BETWEEN 2 AND 6) SELECT id, page, event_time, clean_page, island_id, duration_sec_bucket, island_id_whole, event_time_label FROM cleaned_web_events ORDER BY event_time DESC NULLS LAST
